void abbreviate(final int nameStart, final StringBuffer buf) {
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Name start index out of bounds");
    }
    if (buf.length() - nameStart < 3) {
        throw new IllegalArgumentException("Name too short to abbreviate");
    }
    buf.append(buf.charAt(nameStart));
    buf.append('.');
    int i = nameStart + 1;
    while (i < buf.length() && !Character.isWhitespace(buf.charAt(i))) {
        i++;
    }
    if (i >= buf.length()) {
        throw new IllegalArgumentException("No whitespace found after name start index");
    }
    buf.append(buf.charAt(i));
}

